(6420370, 951558, 61396, '<td valign="top">Complementing colors work exceptional well here.</td>', 'Complementing colors work exceptional well here.', '2011-05-21 10:40:31.000000', NULL, 1),
(6420372, 951780, 61396, '<td valign="top">I like the multiple play of of light, and I admire the touch added by the lamp on the right.</td>', 'I like the multiple play of of light, and I admire the touch added by the lamp on the right.', '2011-05-21 10:47:43.000000', NULL, 1),
(6420407, 951725, 132021, '<td valign="top">Wow! Wish we had a scene like this in the U.S.! Gorgeous! Not the biggest fan of the composition, something really needs to warrant a squarish crop for me. I go back and forth though, because the texturing in the clouds really does add. hhmmm.</td>', 'Wow! Wish we had a scene like this in the U.S.! Gorgeous! Not the biggest fan of the composition, something really needs to warrant a squarish crop for me. I go back and forth though, because the texturing in the clouds really does add. hhmmm.', '2011-05-21 11:13:38.000000', NULL, 1),
(6420409, 951597, 132021, '<td valign="top">My god look at those colors! The rock in the lower right is a bit distracting. Then again, the photo may have been a bit "to balanced" if it weren''t there. Great photo!</td>', 'My god look at those colors! The rock in the lower right is a bit distracting. Then again, the photo may have been a bit "to balanced" if it weren''t there. Great photo!', '2011-05-21 11:15:02.000000', NULL, 1),
(6420428, 951765, 132021, '<td valign="top">I like the idea here. Straight profile shots are hard to pull off though. Plus, the cantered horizon doesn''t add anything for me. Perhaps if you went lower, and took the shot from about the drivers 10 o''clock, just to get a bit of the front end, it would have added a bit more life to the shot.</td>', 'I like the idea here. Straight profile shots are hard to pull off though. Plus, the cantered horizon doesn''t add anything for me. Perhaps if you went lower, and took the shot from about the drivers 10 o''clock, just to get a bit of the front end, it would have added a bit more life to the shot.', '2011-05-21 11:21:51.000000', NULL, 1),
(6420435, 951709, 132021, '<td valign="top">Oh wow. What an interesting shot! Give me a bit of a good headache. I would be interested to see the shot cropped a bit tigher to remove the building in the lower left and trees in teh lower right to enhance the patterness of the buildings. Definately a cool photo!</td>', 'Oh wow. What an interesting shot! Give me a bit of a good headache. I would be interested to see the shot cropped a bit tigher to remove the building in the lower left and trees in teh lower right to enhance the patterness of the buildings. Definately a cool photo!', '2011-05-21 11:26:04.000000', NULL, 1),
(6420437, 951645, 132021, '<td valign="top">Great colors, subject the whole nine yards. I wouldn''t have gone square crop on it though.</td>', 'Great colors, subject the whole nine yards. I wouldn''t have gone square crop on it though.', '2011-05-21 11:29:47.000000', NULL, 1),
(6420439, 951641, 132021, '<td valign="top">I can''t even imagine how you must have felt after you captured this shot. Wow, what are the chances! Beautiful!</td>', 'I can''t even imagine how you must have felt after you captured this shot. Wow, what are the chances! Beautiful!', '2011-05-21 11:31:01.000000', NULL, 1),
