INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6422183, 951558, 48228, '<td valign="top">I JUST LOVE THIS and cannot explain why I think it the softness and the colors AMAZING and it from an AUSSIE as well ADDED it as a favorite definately a favorite from shez<br/>It also reminds me of our Australian early artists/painters (Heidleburg School) when they painted the real Australia using the wonderful and amazing natural light we see here so often in our landscapes... I love it, thank you for submitting this one, and also very pleased it RIBBONED for YOU..... from shez<br/><br/><i>Message edited by author 2011-05-23 08:03:56.</i></td>', 'I JUST LOVE THIS and cannot explain why I think it the softness and the colors AMAZING and it from an AUSSIE as well ADDED it as a favorite definately a favorite from shezIt also reminds me of our Australian early artists/painters (Heidleburg School) when they painted the real Australia using the wonderful and amazing natural light we see here so often in our landscapes... I love it, thank you for submitting this one, and also very pleased it RIBBONED for YOU..... from shez', '2011-05-23 09:00:06.000000', '2011-05-23 09:03:56.000000', 0),
(6422196, 951558, 123833, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by sherpet:</b></div><hr/><i> I JUST LOVE THIS and cannot explain why I think it the softness and the colors AMAZING and it from an AUSSIE as well ADDED it as a favorite definately a favorite from shez<br/>It also reminds me of our Australian early artists/painters (Heidleburg School) when they painted the real Australia using the wonderful and amazing natural light we see here so often in our landscapes... I love it, thank you for submitting this one, and also very pleased it RIBBONED for YOU..... from shez </i></td></tr></table> <br/>Thanks, Sherryl! I am not far from Heidelberg and quite often cycle along the Yarra where there are big boards with posters of Heildelberg School paintings in spots where they were originally painted. It is nice although I have to admit that I had to work quite a bit on PP to show off these nice colours! (there is not much light at sunrise)</td>', 'Originally posted by sherpet: I JUST LOVE THIS and cannot explain why I think it the softness and the colors AMAZING and it from an AUSSIE as well ADDED it as a favorite definately a favorite from shezIt also reminds me of our Australian early artists/painters (Heidleburg School) when they painted the real Australia using the wonderful and amazing natural light we see here so often in our landscapes... I love it, thank you for submitting this one, and also very pleased it RIBBONED for YOU..... from shez  Thanks, Sherryl! I am not far from Heidelberg and quite often cycle along the Yarra where there are big boards with posters of Heildelberg School paintings in spots where they were originally painted. It is nice although I have to admit that I had to work quite a bit on PP to show off these nice colours! (there is not much light at sunrise)', '2011-05-23 09:18:25.000000', NULL, 0),
(6422198, 951352, 48228, '<td valign="top">JUST DREAMY and so so SPECIAL It is HOME to ME also love from shez</td>', 'JUST DREAMY and so so SPECIAL It is HOME to ME also love from shez', '2011-05-23 09:21:55.000000', NULL, 0),
